(()=>{'use strict';
const P=window.PASSAGES||[], $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)], E=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const L={
 en:{key:'english_rwwad',exp:'ibn',iso:'en',source:'Rowwad Translation Center'},
 bn:{key:'bengali_zakaria',exp:'bengali_mokhtasar',iso:'bn',source:'ড. আবূ বকর মুহাম্মাদ যাকারিয়া'},
 hi:{key:'hindi_omari',exp:'hindi_mokhtasar',iso:'hi',source:'अज़ीज़ुल हक़ उमरी'}
};
const T={
 en:{brand:'Recitation & study library',hero:'Beautiful passages with a <em>build → rise → climax</em>',desc:'Open any selection to study every ayah with Arabic, translation, explanation, Mishary Alafasy audio, personal notes, and source links.',open:'Open study',listen:'Listen ↗',exact:'Exact Mushaf ↗',high:'High point',trans:'Translation',taf:'Explanation / Tafsir',note:'My note for this ayah',loading:'Loading Arabic, audio and translation…',fail:'Live study sources could not be reached. Exact Mushaf and source links are still available.',had:'Load authentic hadith',hadload:'Loading authentic hadith from HadeethEnc…',hadfail:'Could not load HadeethEnc right now.',notes:'Your private notes',save:'Saved automatically',clear:'Clear',src:'Translation source'},
 bn:{brand:'তিলাওয়াত ও অধ্যয়ন লাইব্রেরি',hero:'যে আয়াতগুলোতে আছে <em>শুরু → উত্থান → চূড়ান্ত আবেগ</em>',desc:'যেকোনো অংশ খুলে প্রতিটি আয়াতের আরবি, বাংলা অনুবাদ, ব্যাখ্যা, মিশারী আল-আফাসীর অডিও, ব্যক্তিগত নোট ও উৎস দেখুন।',open:'স্টাডি খুলুন',listen:'শুনুন ↗',exact:'Exact Mushaf ↗',high:'উচ্চ আবেগের অংশ',trans:'অনুবাদ',taf:'ব্যাখ্যা / তাফসীর',note:'এই আয়াতের জন্য আমার নোট',loading:'আরবি, অডিও ও অনুবাদ লোড হচ্ছে…',fail:'কিছু লাইভ উৎসে পৌঁছানো যায়নি। Exact Mushaf ও উৎস লিংক ব্যবহার করা যাবে।',had:'সহীহ হাদীস লোড করুন',hadload:'HadeethEnc থেকে হাদীস লোড হচ্ছে…',hadfail:'এখন HadeethEnc লোড করা যায়নি।',notes:'আপনার ব্যক্তিগত নোট',save:'স্বয়ংক্রিয়ভাবে সংরক্ষিত',clear:'মুছুন',src:'অনুবাদের উৎস'},
 hi:{brand:'तिलावत और अध्ययन लाइब्रेरी',hero:'खूबसूरत हिस्से जिनमें है <em>तैयारी → उभार → चरम</em>',desc:'किसी भी हिस्से को खोलकर हर आयत का अरबी पाठ, हिंदी अनुवाद, व्याख्या, मिशारी अल-अफासी ऑडियो, निजी नोट और स्रोत देखें।',open:'अध्ययन खोलें',listen:'सुनें ↗',exact:'Exact Mushaf ↗',high:'मुख्य चरम',trans:'अनुवाद',taf:'व्याख्या / तफ़्सीर',note:'इस आयत के लिए मेरा नोट',loading:'अरबी, ऑडियो और अनुवाद लोड हो रहे हैं…',fail:'कुछ लाइव स्रोत उपलब्ध नहीं हुए। Exact Mushaf और स्रोत लिंक उपलब्ध हैं।',had:'प्रामाणिक हदीस लोड करें',hadload:'HadeethEnc से हदीस लोड हो रही हैं…',hadfail:'अभी HadeethEnc लोड नहीं हो पाया।',notes:'आपके निजी नोट',save:'अपने-आप सेव',clear:'साफ़ करें',src:'अनुवाद का स्रोत'}
};
function savedFavs(){try{const x=JSON.parse(localStorage.getItem('fqFav')||'[]');return new Set(Array.isArray(x)?x:[])}catch{return new Set()}}
let lang=localStorage.getItem('fqLang')||'en', fav=savedFavs(), onlyFav=false, active=null, currentAudio=null; if(!L[lang])lang='en'; const tr=k=>T[lang][k]||T.en[k]||k;
const grid=$('#grid'), search=$('#search'), tag=$('#tagFilter'), sort=$('#sort'), dlg=$('#studyDialog');
const range=r=>{let n=String(r).match(/\d+/g)?.map(Number)||[1];return[n[0],n[1]||n[0]]}; const mush=p=>Array.isArray(p.read)?p.read[0]:p.read;
async function j(url){let r=await fetch(url,{headers:{Accept:'application/json'}});if(!r.ok)throw new Error(r.status);return r.json()} const data=x=>x?.result??x?.data??x;
async function quranEncMeta(code){try{const cfg=L[code],z=data(await j(`https://quranenc.com/api/v1/translations/list/${cfg.iso}?localization=en`)),a=Array.isArray(z)?z:(z?.translations||[]);return a.find(x=>x.key===cfg.key)||null}catch{return null}}
function applyLang(){document.documentElement.lang=lang;document.body.dataset.lang=lang;localStorage.setItem('fqLang',lang);$$('.lang-btn').forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));$('#brandSub').textContent=tr('brand');$('#heroTitle').innerHTML=tr('hero');$('#heroText').textContent=tr('desc');$('#loadHadith').textContent=tr('had');$('#translationSourceTitle').textContent=tr('src');$('#notesTitle').textContent=tr('notes');$('#notesSaved').textContent=tr('save');$('#clearNotes').textContent=tr('clear');render();if(active&&dlg.open)openStudy(active.rank,true)}
function tags(){[...new Set(P.flatMap(p=>p.tags||[]))].sort().forEach(x=>{let o=document.createElement('option');o.value=x;o.textContent=x;tag.append(o)})}
function render(){let q=search.value.trim().toLowerCase(), xs=P.filter(p=>(!onlyFav||fav.has(p.rank))&&(!tag.value||(p.tags||[]).includes(tag.value))&&(!q||[p.surah,p.arabicName,p.range,p.open,p.peak,p.why,p.evidence,p.signal,...p.reciters,...p.tags].join(' ').toLowerCase().includes(q)));if(sort.value==='surah')xs.sort((a,b)=>a.surahNo-b.surahNo);else if(sort.value==='fav')xs.sort((a,b)=>(fav.has(b.rank)-fav.has(a.rank))||a.rank-b.rank);else xs.sort((a,b)=>a.rank-b.rank);grid.innerHTML=xs.map(p=>`<article class="card"><div class="card-head"><div class="rank">${String(p.rank).padStart(2,'0')}</div><div class="card-title"><h3>Surah ${E(p.surah)} <span class="range">${p.surahNo}:${E(p.range)}</span></h3><div class="meta">${E(p.arabicName)} · ${E(p.peakAt)}</div></div><button class="fav ${fav.has(p.rank)?'on':''}" data-fav="${p.rank}">★</button></div><div class="arabic-preview">${E(p.open)}</div><div class="peakline"><b>${E(tr('high'))}:</b> <span dir="rtl">${E(p.peak)}</span></div><div class="card-tags"><span class="tag signal">${E(p.signal)}</span>${p.tags.map(x=>`<span class="tag">${E(x)}</span>`).join('')}</div><div class="card-actions"><button class="btn primary" data-open="${p.rank}">${E(tr('open'))}</button><a class="btn" target="_blank" rel="noopener" href="${E(p.listen)}">${E(tr('listen'))}</a><a class="btn gold" target="_blank" rel="noopener" href="${E(mush(p))}">${E(tr('exact'))}</a></div></article>`).join('');$('#empty').hidden=!!xs.length}
function summary(p){return `<div class="dialog-kicker">#${p.rank} · ${E(p.signal)}</div><h3>Surah ${E(p.surah)} <span class="range">${p.surahNo}:${E(p.range)}</span></h3><div class="arabic-preview">${E(p.open)}</div><p><b style="color:var(--green2)">${E(tr('high'))}: ${E(p.peakAt)}</b></p><div class="arabic-preview">${E(p.peak)}</div><p>${E(p.why)}</p><p class="view-note">${E(p.evidence)}</p><div class="source-badges">${p.reciters.map(x=>`<span>${E(x)}</span>`).join('')}</div>`}
function tab(n){$$('.tab',dlg).forEach(b=>b.classList.toggle('active',b.dataset.tab===n));$('#ayahPanel').classList.toggle('active',n==='ayahs');$('#notesPanel').classList.toggle('active',n==='notes')}
async function openStudy(rank,refresh=false){let p=P.find(x=>x.rank===+rank);if(!p)return;active=p;$('#dialogKicker').textContent=`#${p.rank} · ${p.signal}`;$('#dialogTitle').textContent=`Surah ${p.surah} — ${p.surahNo}:${p.range}`;$('#passageSummary').innerHTML=summary(p);$('#exactMushaf').href=mush(p);$('#exactMushaf').textContent=tr('exact');$('#recitationLink').href=p.listen;const openedLang=lang;$('#translationSource').textContent=`${L[openedLang].source} · QuranEnc · live API`;quranEncMeta(openedLang).then(m=>{if(m&&active?.rank===p.rank&&lang===openedLang){$('#translationSource').textContent=(m.title||L[openedLang].source)+' · QuranEnc · v'+(m.version||'current')+(m.last_update?' · updated '+String(m.last_update).slice(0,10):'')}});let nk=`fq:passage:${p.surahNo}:${p.range}`;$('#passageNotes').dataset.key=nk;$('#passageNotes').value=localStorage.getItem(nk)||'';tab('ayahs');if(!dlg.open)dlg.showModal();if(!refresh)history.replaceState(null,'',`#p${p.rank}`);await loadAyahs(p)}
async function loadAyahs(p){let panel=$('#ayahPanel');panel.innerHTML=`<div class="status-card">${E(tr('loading'))}</div>`;let [a,b]=range(p.range),cfg=L[lang];try{let [trs,ar,au]=await Promise.all([j(`https://quranenc.com/api/v1/translation/sura/${cfg.key}/${p.surahNo}`),j(`https://api.alquran.cloud/v1/surah/${p.surahNo}/quran-uthmani`),j(`https://api.alquran.cloud/v1/surah/${p.surahNo}/ar.alafasy`)]);trs=data(trs);if(!Array.isArray(trs))trs=trs?.translations||[];let aa=data(ar)?.ayahs||[], uu=data(au)?.ayahs||[];panel.innerHTML='';for(let n=a;n<=b;n++){let t=trs.find(x=>+x.aya===n)||{}, x=aa.find(x=>+x.numberInSurah===n)||{}, u=uu.find(x=>+x.numberInSurah===n)||{};panel.append(ayahCard(p,n,x,u,t))}}catch(e){panel.innerHTML=`<div class="status-card error-line">${E(tr('fail'))}<br><br><a class="btn gold" target="_blank" rel="noopener" href="${E(mush(p))}">${E(tr('exact'))}</a></div>`}}
function ayahCard(p,n,ar,au,t){let node=$('#ayahTemplate').content.firstElementChild.cloneNode(true);$('.ayah-number',node).textContent=`${p.surahNo}:${n}`;$('.ayah-arabic',node).textContent=ar.text||'';$('.translation-label',node).textContent=tr('trans');let tmp=document.createElement('div');tmp.innerHTML=t.translation||'—';$('.ayah-translation',node).textContent=tmp.textContent||'—';let ft=t.footnotes||'';tmp.innerHTML=ft;$('.footnotes',node).textContent=tmp.textContent||'';$('summary.explanation-label',node).textContent=tr('taf');$('summary.note-label',node).textContent=tr('note');let q=$('.tafsir-link',node);q.href=`https://quran.com/${p.surahNo}:${n}/tafsirs/en-tafisr-ibn-kathir`;let audio=$('.ayah-audio',node),btn=$('.play-btn',node);audio.src=au.audio||'';btn.hidden=!au.audio;btn.onclick=()=>{if(currentAudio&&currentAudio!==audio)currentAudio.pause();if(audio.paused){audio.play();currentAudio=audio;btn.classList.add('playing')}else{audio.pause();btn.classList.remove('playing')}};let det=$('.tafsir-details',node),out=$('.ayah-tafsir',node),loaded=false;det.ontoggle=async()=>{if(det.open&&!loaded){loaded=true;out.textContent='…';try{if(lang==='en'){let z=await j(`https://alfurqan.online/api/v1/tafseer/ibn-kathir-english/surah/${p.surahNo}/ayah/${n}`);out.textContent=z?.ayah?.text||z?.text||z?.data?.ayah?.text||'—'}else{let z=data(await j(`https://quranenc.com/api/v1/translation/aya/${L[lang].exp}/${p.surahNo}/${n}`));tmp.innerHTML=z?.translation||z?.text||'—';out.textContent=tmp.textContent||'—'}}catch(e){out.textContent=tr('fail')}}};let ta=$('.ayah-note',node),key=`fq:ayah:${p.surahNo}:${n}`;ta.value=localStorage.getItem(key)||'';ta.oninput=()=>localStorage.setItem(key,ta.value);return node}
async function loadHadith(){let st=$('#hadithStatus'),out=$('#hadithGrid');st.hidden=false;st.textContent=tr('hadload');out.innerHTML='';try{let cats=data(await j('https://hadeethenc.com/api/v1/categories/list/?language=en')),arr=Array.isArray(cats)?cats:cats?.data||[],c=arr.find(x=>/qur|koran/i.test(x.title||''));if(!c)throw 0;let z=await j(`https://hadeethenc.com/api/v1/hadeeths/list/?language=${L[lang].iso}&category_id=${c.id}&page=1&per_page=6`),hs=z?.data||data(z)?.data||data(z)||[];if(!Array.isArray(hs)||!hs.length)throw 0;st.hidden=true;out.innerHTML=hs.map(h=>`<article class="hadith-card"><div class="hadith-grade">${E(h.grade||'HadeethEnc')}</div><h3>${E(h.title||'Hadith')}</h3><p>${E(h.hadeeth||h.hadith||'')}</p>${h.attribution?`<p class="view-note"><b>Attribution:</b> ${E(h.attribution)}</p>`:''}${h.reference?`<p class="view-note"><b>Reference:</b> ${E(h.reference)}</p>`:''}${h.explanation?`<details><summary>Explanation</summary><p>${E(h.explanation)}</p></details>`:''}<a target="_blank" rel="noopener" href="https://hadeethenc.com/${L[lang].iso}/browse/hadith/${E(h.id||'')}">HadeethEnc source ↗</a></article>`).join('')}catch(e){st.textContent=tr('hadfail')}}
grid.onclick=e=>{let f=e.target.closest('[data-fav]');if(f){let n=+f.dataset.fav;fav.has(n)?fav.delete(n):fav.add(n);localStorage.setItem('fqFav',JSON.stringify([...fav]));render();return}let o=e.target.closest('[data-open]');if(o)openStudy(o.dataset.open)};[search,tag,sort].forEach(x=>x.addEventListener(x===search?'input':'change',render));$$('.lang-btn').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;applyLang()});$('#favoritesToggle').onclick=()=>{onlyFav=!onlyFav;$('#favoritesToggle').classList.toggle('active',onlyFav);render()};$('#hadithJump').onclick=()=>$('#hadith').scrollIntoView({behavior:'smooth'});$('#loadHadith').onclick=loadHadith;$('#closeDialog').onclick=()=>dlg.close();dlg.onclick=e=>{if(e.target===dlg)dlg.close()};dlg.onclose=()=>{if(currentAudio)currentAudio.pause();history.replaceState(null,'',location.pathname+location.search)};$$('.tab',dlg).forEach(b=>b.onclick=()=>tab(b.dataset.tab));$('#passageNotes').oninput=e=>localStorage.setItem(e.target.dataset.key,e.target.value);$('#clearNotes').onclick=()=>{let x=$('#passageNotes');localStorage.removeItem(x.dataset.key);x.value=''};tags();applyLang();let m=location.hash.match(/^#p(\d+)$/);if(m)setTimeout(()=>openStudy(m[1]),50)
})();
